syntax:
template<typename T, typename U = DefaultType>
class ClassName {
    // class members
};

code_example:
#include <iostream>

template<typename T, typename Traits = std::char_traits<T>>
class BasicStreamBuffer {
public:
    void display() {
        std::cout << "Template class with default parameter" << std::endl;
    }
};

int main() {
    BasicStreamBuffer<char> buffer;
    buffer.display();
    return 0;
}
